async function setup(adapter?:Partial<UhpAdapter>) { const dir=await mkdtemp(join(tmpdir(),'foreman-'));dirs.push(dir);const store=new JsonStore(join(dir,'state.json'));const calls:{input:any}[]=[];let controller:Controller;const uhp:UhpAdapter={...adapter,submit:async input=>{calls.push({input});const response=adapter?.submit?await adapter.submit(input):{externalId:'external-1',status:'completed',result:{ok:true}};if(input.roleId==='reviewer'&&response.reviewerExecution&&!response.reviewerExecution.contextDigest){const digest=(input.config.reviewEvidence as any)?.reviewContextDigest;if(typeof digest==='string')response.reviewerExecution.contextDigest=digest;}return response;},cancel:adapter?.cancel??(async()=>({status:'cancelled'}))};await store.mutate(s=>{for(const role of s.roles){role.enabled=true;role.availableConfigs=[{harnessId:'fixture',model:'model-fixture'}];role.config={harnessId:'fixture',model:'model-fixture'};}});controller=new Controller(store,uhp);return {dir,store,controller,calls,uhp}; }
async function waitForController(store:JsonStore,runId:string){for(let i=0;i<500;i++){const state=await store.load();const run=state.projects.flatMap(p=>p.tasks.flatMap(t=>t.runs)).find(r=>r.id===runId);if(run?.controller&&!run.controller.active)return run;await new Promise(resolve=>setTimeout(resolve,5));}throw new Error(`Automatic run ${runId} did not reach a terminal controller state`);}
async function prepareAutomaticRun(controller:Controller,store:JsonStore){
  controller.configureVerifiedWorkspace({repoPath:'/fixture/repo',bridgeBaseUrl:'http://127.0.0.1:1',allowedScope:['README.md'],commands:[{name:'fixture check',command:'true',args:[]}]});
  const project:any=await controller.createProject('Automatic workflow'),task:any=await controller.createTask(project.id,'Bounded task'),run:any=await controller.createRun(task.id);
  await store.mutate(s=>{const current=s.projects[0]!.tasks[0]!.runs[0]!;current.pinnedBaseCommit='a'.repeat(40);current.workspaceId='prepared-fixture-workspace';});
  await controller.addGuidance(run.id,'Make the requested small README change.');
  return run;
}
