    await store.mutate(s=>{const current=s.projects[0]!.tasks[0]!.runs[0]!;current.projectPlannerContext='Planner task framing';current.allowedScope=['README.md'];current.pinnedBaseCommit='a'.repeat(40);current.workspaceId='prepared-research-workspace';});
    await controller.addGuidance(run.id,'Research documented behavior, then implement within the goal.');
    const result=await controller.orchestrate(run.id,'Research the documented endpoint behavior.');
